from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    tiles = list(tiles[:n])
    total = h * w
    full = (1 << total) - 1
    areas = [a * b for a, b in tiles]
    # Each tile placement is represented by a bit mask in row-major cell order.
    placements = []
    for a, b in tiles:
        choices = {(a, b), (b, a)}
        masks = {}
        for th, tw in choices:
            if th <= h and tw <= w:
                for r in range(h - th + 1):
                    for c in range(w - tw + 1):
                        mask = 0
                        row_bits = (1 << tw) - 1
                        for dr in range(th):
                            mask |= row_bits << ((r + dr) * w + c)
                        masks[(r, c, th, tw)] = mask
        placements.append(masks)

    from functools import lru_cache

    @lru_cache(None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        missing = total - occupied.bit_count()
        if sum(areas[i] for i in range(len(tiles)) if not (used >> i) & 1) < missing:
            return False

        # The first uncovered cell must be the top-left cell of any tile covering it:
        # extending above or to its left would overlap an earlier uncovered-order cell.
        pos = 0
        while (occupied >> pos) & 1:
            pos += 1
        r, c = divmod(pos, w)

        tried = set()
        for i, tile_masks in enumerate(placements):
            if (used >> i) & 1:
                continue
            dims = tiles[i]
            canonical = tuple(sorted(dims))
            if canonical in tried:
                continue
            tried.add(canonical)
            for (pr, pc, th, tw), mask in tile_masks.items():
                if pr == r and pc == c and not (occupied & mask):
                    if search(occupied | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

