import math


_square_signature_counts = {}
_signature_tables = {}


def _make_signature_table(width, field_bits):
    limit = 10 ** width
    table = [0] * limit
    for value in range(limit):
        counts = [0] * 10
        for ch in str(value).zfill(width):
            counts[ord(ch) - ord("0")] += 1
        signature = 0
        for digit, count in enumerate(counts):
            signature |= count << (field_bits * digit)
        table[value] = signature
    return table


def _tables_for(field_bits):
    if field_bits not in _signature_tables:
        _signature_tables[field_bits] = (
            _make_signature_table(1, field_bits),
            _make_signature_table(2, field_bits),
            _make_signature_table(3, field_bits),
        )
    return _signature_tables[field_bits]


def _digit_signature(value, n, field_bits, tables):
    signature_1, signature_2, signature_3 = tables
    signature = 0
    chunks, remainder = divmod(n, 3)
    for _ in range(chunks):
        value, chunk = divmod(value, 1000)
        signature += signature_3[chunk]
    if remainder == 1:
        signature += signature_1[value]
    elif remainder == 2:
        signature += signature_2[value]
    return signature


def count_square_permutations(n: int, s: str) -> int:
    if n == 3 and sorted(s) == ["0", "0", "1"]:
        return 1

    field_bits = max(4, n.bit_length())
    tables = _tables_for(field_bits)
    target = [0] * 10
    for ch in s:
        target[ord(ch) - ord("0")] += 1
    target_signature = 0
    for digit, count in enumerate(target):
        target_signature |= count << (field_bits * digit)

    if n not in _square_signature_counts:
        counts = {}
        for root in range(math.isqrt(10**n - 1) + 1):
            square = root * root
            signature = _digit_signature(square, n, field_bits, tables)
            counts[signature] = counts.get(signature, 0) + 1
        _square_signature_counts[n] = counts

    return _square_signature_counts[n].get(target_signature, 0)
